def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    if n < 8:
        if opp.count('D') >= 2:
            return 'D'
        return 'C'
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def_total = sum(1 for a in opp if a == 'D')
    me_def_total = sum(1 for a in me if a == 'D')
    opp_def10 = sum(1 for a in opp[-10:] if a == 'D')
    me_def10 = sum(1 for a in me[-10:] if a == 'D')
    opp_coop_rate = (n - opp_def_total) / n
    if n >= 90:
        if opp_coop_rate >= 0.5:
            return 'D'
        if opp_def10 >= 7:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D' if rng.random() < 0.8 else 'C'
    if opp_def10 >= 8:
        return 'D'
    if n >= 20:
        recent_opp_def = sum(1 for a in opp[-5:] if a == 'D')
        earlier_opp_def = sum(1 for a in opp[-20:-5] if a == 'D')
        if recent_opp_def >= 3 and earlier_opp_def <= 1:
            return 'D'
    if n >= 15:
        alt = True
        for i in range(max(1, n - 6), n):
            if opp[i] == opp[i - 1]:
                alt = False
                break
        if alt and n >= 8:
            if opp[-1] == 'C':
                return 'D'
            return 'C'
    if last_opp == 'D' and last_me == 'C':
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'
        if opp_def_total <= 2 and n >= 10:
            if rng.random() < 0.6:
                return 'C'
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if n >= 4 and opp[-3:-1] == ['C', 'C']:
            return 'C'
        if n >= 6 and sum(1 for a in opp[-6:] if a == 'C') >= 3:
            return 'C'
        return 'D'
    if last_opp == 'C':
        if opp_def_total == 0 and n >= 20:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if me_def10 >= 6:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if opp_def10 >= 5:
            if rng.random() < 0.3:
                return 'D'
        if n >= 25 and opp_coop_rate > 0.85 and me_def_total >= 1:
            if rng.random() < 0.2:
                return 'D'
        return 'C'
    return 'C'
